#!/usr/bin/env bash\nset -e\n# Resolve the directory of this script\nDIR=$(cd "$(dirname "$0")" && pwd)\nACTION_FILE="$DIR/../action.yml"\n# Verify that the action uses actions/github-script@v6\nif grep -q "uses: actions/github-script@v6" "$ACTION_FILE"; then\n  echo "Test passed: actions/github-script@v6 found in action.yml"\n  exit 0\nelse\n  echo "Test failed: actions/github-script@v6 not found in action.yml"\n  exit 1\nfi\n
